arguments.new_str:
class EnvVarCheck
{
    void CheckFlag()
    {
        // On Linux, set via: export MY_FLAG=""
        // .NET 9 no longer treats empty env vars as unset — they return ""
        // instead of null. Use a separate existence check to distinguish
        // "not set" from "explicitly empty".
        var val = Environment.GetEnvironmentVariable("MY_FLAG");
        if (val == null && !IsEnvironmentVariableDefined("MY_FLAG"))
        {
            Console.WriteLine("MY_FLAG not set, using default");
        }
    }

    private static bool IsEnvironmentVariableDefined(string name)
    {
        // Environment.GetEnvironmentVariables() includes vars set to ""
        return Environment.GetEnvironmentVariables().Contains(name);
    }
}

